7	import * as crypto from 'node:crypto';
8	import { coreEvents } from '../utils/events.js';
9	import { KeychainAvailabilityEvent } from '../telemetry/types.js';
10	import { debugLogger } from '../utils/debugLogger.js';
11	import {
12	  type Keychain,
13	  KeychainSchema,
14	  KEYCHAIN_TEST_PREFIX,
15	} from './keychainTypes.js';
16	import { isRecord } from '../utils/markdownUtils.js';
17	import { FileKeychain } from './fileKeychain.js';
18	
19	export const FORCE_FILE_STORAGE_ENV_VAR = 'GEMINI_FORCE_FILE_STORAGE';
20	
21	/**
22	 * Service for interacting with OS-level secure storage (e.g. keytar).
23	 */
24	export class KeychainService {
25	  // Track an ongoing initialization attempt to avoid race conditions.
26	  private initializationPromise?: Promise<Keychain | null>;
27	
28	  /**
29	   * @param serviceName Unique identifier for the app in the OS keychain.
30	   */
31	  constructor(private readonly serviceName: string) {}
32	
33	  async isAvailable(): Promise<boolean> {
34	    return (await this.getKeychain()) !== null;
35	  }
36	
37	  /**
38	   * Returns true if the service is using the encrypted file fallback backend.
39	   */
40	  async isUsingFileFallback(): Promise<boolean> {
41	    const keychain = await this.getKeychain();
42	    return keychain instanceof FileKeychain;
43	  }
44	
45	  /**
46	   * Retrieves a secret for the given account.
47	   * @throws Error if the keychain is unavailable.
48	   */
49	  async getPassword(account: string): Promise<string | null> {
50	    const keychain = await this.getKeychainOrThrow();
51	    return keychain.getPassword(this.serviceName, account);
52	  }
53	
54	  /**
55	   * Securely stores a secret.
56	   * @throws Error if the keychain is unavailable.
57	   */
58	  async setPassword(account: string, value: string): Promise<void> {
59	    const keychain = await this.getKeychainOrThrow();
60	    await keychain.setPassword(this.serviceName, account, value);
61	  }
62	
63	  /**
64	   * Removes a secret from the keychain.
65	   * @returns true if the secret was deleted, false otherwise.
66	   * @throws Error if the keychain is unavailable.
67	   */
68	  async deletePassword(account: string): Promise<boolean> {
69	    const keychain = await this.getKeychainOrThrow();
70	    return keychain.deletePassword(this.serviceName, account);
71	  }
72	
73	  /**
74	   * Lists all account/secret pairs stored under this service.
75	   * @throws Error if the keychain is unavailable.
76	   */
77	  async findCredentials(): Promise<
78	    Array<{ account: string; password: string }>
79	  > {
80	    const keychain = await this.getKeychainOrThrow();
81	    return keychain.findCredentials(this.serviceName);
82	  }
83	
84	  private async getKeychainOrThrow(): Promise<Keychain> {
85	    const keychain = await this.getKeychain();
86	    if (!keychain) {
87	      throw new Error('Keychain is not available');
88	    }
89	    return keychain;
90	  }
91	
92	  private getKeychain(): Promise<Keychain | null> {
93	    return (this.initializationPromise ??= this.initializeKeychain());
94	  }
95	
96	  // High-level orchestration of the loading and testing cycle.
97	  private async initializeKeychain(): Promise<Keychain | null> {
98	    let resultKeychain: Keychain | null = null;
99	    const forceFileStorage = process.env[FORCE_FILE_STORAGE_ENV_VAR] === 'true';
100	
101	    if (!forceFileStorage) {
102	      try {
103	        const keychainModule = await this.loadKeychainModule();
104	        if (keychainModule) {
105	          if (await this.isKeychainFunctional(keychainModule)) {
106	            resultKeychain = keychainModule;
107	          } else {
108	            debugLogger.log('Keychain functional verification failed');
109	          }
110	        }
111	      } catch (error) {
112	        // Avoid logging full error objects to prevent PII exposure.
113	        const message = error instanceof Error ? error.message : String(error);
114	        debugLogger.log(
115	          'Keychain initialization encountered an error:',
116	          message,
117	        );
118	      }
119	    }
120	
121	    coreEvents.emitTelemetryKeychainAvailability(
122	      new KeychainAvailabilityEvent(
123	        resultKeychain !== null && !forceFileStorage,
124	      ),
125	    );
126	
127	    // Fallback to FileKeychain if native keychain is unavailable or file storage is forced
128	    if (!resultKeychain) {
129	      resultKeychain = new FileKeychain();
130	      debugLogger.log('Using FileKeychain fallback for secure storage.');
131	    }
132	
133	    return resultKeychain;
134	  }
135	
136	  // Low-level dynamic loading and structural validation.
137	  private async loadKeychainModule(): Promise<Keychain | null> {
138	    const moduleName = 'keytar';
139	    const module: unknown = await import(moduleName);
140	    const potential = (isRecord(module) && module['default']) || module;
141	
142	    const result = KeychainSchema.safeParse(potential);
143	    if (result.success) {
144	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
145	      return potential as Keychain;
146	    }
147	
148	    debugLogger.log(
149	      'Keychain module failed structural validation:',
150	      result.error.flatten().fieldErrors,
151	    );
152	    return null;
153	  }
154	
155	  // Performs a set-get-delete cycle to verify keychain functionality.
156	  private async isKeychainFunctional(keychain: Keychain): Promise<boolean> {
157	    const testAccount = `${KEYCHAIN_TEST_PREFIX}${crypto.randomBytes(8).toString('hex')}`;
158	    const testPassword = 'test';
159	
160	    await keychain.setPassword(this.serviceName, testAccount, testPassword);
161	    const retrieved = await keychain.getPassword(this.serviceName, testAccount);
162	    const deleted = await keychain.deletePassword(
163	      this.serviceName,
164	      testAccount,
165	    );
166	
167	    return deleted && retrieved === testPassword;
168	  }
169	}
