112	    super(options.eventEmitter);
113	    this.workspaceDir = options.workspaceDir;
114	    this.extensionEnablementManager = new ExtensionEnablementManager(
115	      options.enabledExtensionOverrides,
116	    );
117	    this.settings = options.settings;
118	    this.telemetryConfig = new Config({
119	      telemetry: options.settings.telemetry,
120	      interactive: false,
121	      sessionId: randomUUID(),
122	      clientVersion: options.clientVersion ?? 'unknown',
123	      targetDir: options.workspaceDir,
124	      cwd: options.workspaceDir,
125	      model: '',
126	      debugMode: false,
127	    });
128	    this.requestConsent = options.requestConsent;
129	    this.requestSetting = options.requestSetting ?? undefined;
130	  }
