157	  async installOrUpdateExtension(
158	    installMetadata: ExtensionInstallMetadata,
159	    previousExtensionConfig?: ExtensionConfig,
160	    requestConsentOverride?: (consent: string) => Promise<boolean>,
161	  ): Promise<GeminiCLIExtension> {
162	    if (
163	      this.settings.security?.allowedExtensions &&
164	      this.settings.security?.allowedExtensions.length > 0
165	    ) {
