7	import * as crypto from 'node:crypto';
8	import * as fs from 'node:fs/promises';
9	import * as path from 'node:path';
10	import { Storage } from '../config/storage.js';
11	import { readPolicyFiles } from './toml-loader.js';
12	import { debugLogger } from '../utils/debugLogger.js';
13	import { isNodeError } from '../utils/errors.js';
14	
15	export enum IntegrityStatus {
16	  MATCH = 'MATCH',
17	  MISMATCH = 'MISMATCH',
18	  NEW = 'NEW',
19	}
20	
21	export interface IntegrityResult {
22	  status: IntegrityStatus;
23	  hash: string;
24	  fileCount: number;
25	}
26	
27	interface StoredIntegrityData {
28	  [key: string]: string; // key = scope:identifier, value = hash
29	}
30	
31	export class PolicyIntegrityManager {
32	  /**
33	   * Checks the integrity of policies in a given directory against the stored hash.
34	   *
35	   * @param scope The scope of the policy (e.g., 'project', 'user').
36	   * @param identifier A unique identifier for the policy scope (e.g., project path).
37	   * @param policyDir The directory containing the policy files.
38	   * @returns IntegrityResult indicating if the current policies match the stored hash.
39	   */
40	  async checkIntegrity(
41	    scope: string,
42	    identifier: string,
43	    policyDir: string,
44	  ): Promise<IntegrityResult> {
45	    const { hash: currentHash, fileCount } =
46	      await PolicyIntegrityManager.calculateIntegrityHash(policyDir);
47	    const storedData = await this.loadIntegrityData();
48	    const key = this.getIntegrityKey(scope, identifier);
49	    const storedHash = storedData[key];
50	
51	    if (!storedHash) {
52	      return { status: IntegrityStatus.NEW, hash: currentHash, fileCount };
53	    }
54	
55	    if (storedHash === currentHash) {
56	      return { status: IntegrityStatus.MATCH, hash: currentHash, fileCount };
57	    }
58	
59	    return { status: IntegrityStatus.MISMATCH, hash: currentHash, fileCount };
60	  }
61	
62	  /**
63	   * Accepts and persists the current integrity hash for a given policy scope.
64	   *
65	   * @param scope The scope of the policy.
66	   * @param identifier A unique identifier for the policy scope (e.g., project path).
67	   * @param hash The hash to persist.
68	   */
69	  async acceptIntegrity(
70	    scope: string,
71	    identifier: string,
72	    hash: string,
73	  ): Promise<void> {
74	    const storedData = await this.loadIntegrityData();
75	    const key = this.getIntegrityKey(scope, identifier);
76	    storedData[key] = hash;
77	    await this.saveIntegrityData(storedData);
78	  }
79	
80	  /**
81	   * Calculates a SHA-256 hash of all policy files in the directory.
82	   * The hash includes the relative file path and content to detect renames and modifications.
83	   *
84	   * @param policyDir The directory containing the policy files.
85	   * @returns The calculated hash and file count
86	   */
87	  private static async calculateIntegrityHash(
88	    policyDir: string,
89	  ): Promise<{ hash: string; fileCount: number }> {
90	    try {
91	      const files = await readPolicyFiles(policyDir);
92	
93	      // Sort files by path to ensure deterministic hashing
94	      files.sort((a, b) => a.path.localeCompare(b.path));
95	
96	      const hash = crypto.createHash('sha256');
97	
98	      for (const file of files) {
99	        const relativePath = path.relative(policyDir, file.path);
100	        // Include relative path and content in the hash
101	        hash.update(relativePath);
102	        hash.update('\0'); // Separator
103	        hash.update(file.content);
104	        hash.update('\0'); // Separator
105	      }
106	
107	      return { hash: hash.digest('hex'), fileCount: files.length };
108	    } catch (error) {
109	      debugLogger.error('Failed to calculate policy integrity hash', error);
110	      // Return a unique hash (random) to force a mismatch if calculation fails?
111	      // Or throw? Throwing is better so we don't accidentally accept/deny corrupted state.
112	      throw error;
113	    }
114	  }
115	
116	  private getIntegrityKey(scope: string, identifier: string): string {
117	    return `${scope}:${identifier}`;
118	  }
119	
120	  private async loadIntegrityData(): Promise<StoredIntegrityData> {
121	    const storagePath = Storage.getPolicyIntegrityStoragePath();
122	    try {
123	      const content = await fs.readFile(storagePath, 'utf-8');
124	      const parsed: unknown = JSON.parse(content);
125	      if (
126	        typeof parsed === 'object' &&
127	        parsed !== null &&
128	        Object.values(parsed).every((v) => typeof v === 'string')
129	      ) {
130	        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
131	        return parsed as StoredIntegrityData;
132	      }
133	      debugLogger.warn('Invalid policy integrity data format');
134	      return {};
135	    } catch (error) {
136	      if (isNodeError(error) && error.code === 'ENOENT') {
137	        return {};
138	      }
139	      debugLogger.error('Failed to load policy integrity data', error);
140	      return {};
141	    }
142	  }
143	
144	  private async saveIntegrityData(data: StoredIntegrityData): Promise<void> {
145	    const storagePath = Storage.getPolicyIntegrityStoragePath();
146	    try {
147	      await fs.mkdir(path.dirname(storagePath), { recursive: true });
148	      await fs.writeFile(storagePath, JSON.stringify(data, null, 2), 'utf-8');
149	    } catch (error) {
150	      debugLogger.error('Failed to save policy integrity data', error);
151	      throw error;
152	    }
153	  }
154	}
