29	export async function updateExtension(
30	  extension: GeminiCLIExtension,
31	  extensionManager: ExtensionManager,
32	  currentState: ExtensionUpdateState,
33	  dispatchExtensionStateUpdate: (action: ExtensionUpdateAction) => void,
34	  enableExtensionReloading?: boolean,
35	): Promise<ExtensionUpdateInfo | undefined> {
36	  if (currentState === ExtensionUpdateState.UPDATING) {
37	    return undefined;
38	  }
39	  dispatchExtensionStateUpdate({
40	    type: 'SET_STATE',
41	    payload: { name: extension.name, state: ExtensionUpdateState.UPDATING },
42	  });
43	  const installMetadata = loadInstallMetadata(extension.path);
44	
45	  if (!installMetadata?.type) {
46	    dispatchExtensionStateUpdate({
47	      type: 'SET_STATE',
48	      payload: { name: extension.name, state: ExtensionUpdateState.ERROR },
49	    });
50	    throw new Error(
51	      `Extension ${extension.name} cannot be updated, type is unknown.`,
52	    );
53	  }
54	  if (installMetadata?.type === 'link') {
55	    dispatchExtensionStateUpdate({
56	      type: 'SET_STATE',
57	      payload: { name: extension.name, state: ExtensionUpdateState.UP_TO_DATE },
58	    });
59	    throw new Error(`Extension is linked so does not need to be updated`);
60	  }
61	
62	  if (extension.migratedTo) {
63	    const migratedState = await checkForExtensionUpdate(
64	      {
65	        ...extension,
66	        installMetadata: { ...installMetadata, source: extension.migratedTo },
67	        migratedTo: undefined,
68	      },
69	      extensionManager,
70	    );
71	    if (
72	      migratedState === ExtensionUpdateState.UPDATE_AVAILABLE ||
73	      migratedState === ExtensionUpdateState.UP_TO_DATE
74	    ) {
75	      installMetadata.source = extension.migratedTo;
76	    }
77	  }
78	
79	  const originalVersion = extension.version;
80	
81	  const tempDir = await ExtensionStorage.createTmpDir();
82	  try {
83	    const previousExtensionConfig = await extensionManager.loadExtensionConfig(
84	      extension.path,
85	    );
86	    let updatedExtension: GeminiCLIExtension;
87	    try {
88	      updatedExtension = await extensionManager.installOrUpdateExtension(
89	        installMetadata,
90	        previousExtensionConfig,
91	      );
92	    } catch (e) {
93	      dispatchExtensionStateUpdate({
94	        type: 'SET_STATE',
95	        payload: { name: extension.name, state: ExtensionUpdateState.ERROR },
96	      });
97	      throw new Error(
98	        `Updated extension not found after installation, got error:\n${e}`,
99	      );
100	    }
101	    const updatedVersion = updatedExtension.version;
102	    dispatchExtensionStateUpdate({
103	      type: 'SET_STATE',
104	      payload: {
105	        name: extension.name,
106	        state: enableExtensionReloading
107	          ? ExtensionUpdateState.UPDATED
108	          : ExtensionUpdateState.UPDATED_NEEDS_RESTART,
109	      },
110	    });
111	    return {
112	      name: extension.name,
113	      originalVersion,
114	      updatedVersion,
115	    };
116	  } catch (e) {
117	    debugLogger.error(
118	      `Error updating extension, rolling back. ${getErrorMessage(e)}`,
119	    );
120	    dispatchExtensionStateUpdate({
121	      type: 'SET_STATE',
122	      payload: { name: extension.name, state: ExtensionUpdateState.ERROR },
123	    });
124	    await copyExtension(tempDir, extension.path);
125	    throw e;
126	  } finally {
127	    await fs.promises.rm(tempDir, { recursive: true, force: true });
128	  }
129	}
