28	  name?: string;
29	  all?: boolean;
30	}
31	
32	const updateOutput = (info: ExtensionUpdateInfo) =>
33	  `Extension "${info.name}" successfully updated: ${info.originalVersion} → ${info.updatedVersion}.`;
34	
35	export async function handleUpdate(args: UpdateArgs) {
36	  const workspaceDir = process.cwd();
37	  const settings = loadSettings(workspaceDir).merged;
38	  const extensionManager = new ExtensionManager({
39	    workspaceDir,
40	    requestConsent: requestConsentNonInteractive,
41	    requestSetting: promptForSetting,
42	    settings,
43	  });
44	
45	  const extensions = await extensionManager.loadExtensions();
46	  if (args.name) {
47	    try {
48	      const extension = extensions.find(
49	        (extension) => extension.name === args.name,
50	      );
51	      if (!extension) {
52	        if (extensions.length === 0) {
53	          coreEvents.emitFeedback(
54	            'error',
55	            `Extension "${args.name}" not found.\n\nNo extensions installed.`,
56	          );
57	          return;
58	        }
59	
60	        const installedExtensions = extensions
61	          .map((extension) => `${extension.name} (${extension.version})`)
62	          .join('\n');
63	        coreEvents.emitFeedback(
64	          'error',
65	          `Extension "${args.name}" not found.\n\nInstalled extensions:\n${installedExtensions}\n\nRun "gemini extensions list" for details.`,
66	        );
67	        return;
68	      }
69	      if (!extension.installMetadata) {
70	        debugLogger.log(
71	          `Unable to install extension "${args.name}" due to missing install metadata`,
72	        );
73	        return;
74	      }
75	      const updateState = await checkForExtensionUpdate(
76	        extension,
77	        extensionManager,
78	      );
79	      if (updateState !== ExtensionUpdateState.UPDATE_AVAILABLE) {
80	        debugLogger.log(`Extension "${args.name}" is already up to date.`);
81	        return;
82	      }
83	      const updatedExtensionInfo = (await updateExtension(
84	        extension,
85	        extensionManager,
86	        updateState,
87	        () => {},
88	        settings.experimental?.extensionReloading,
89	      ))!;
90	      if (
91	        updatedExtensionInfo.originalVersion !==
92	        updatedExtensionInfo.updatedVersion
93	      ) {
94	        debugLogger.log(
95	          `Extension "${args.name}" successfully updated: ${updatedExtensionInfo.originalVersion} → ${updatedExtensionInfo.updatedVersion}.`,
96	        );
97	      } else {
98	        debugLogger.log(`Extension "${args.name}" is already up to date.`);
99	      }
100	    } catch (error) {
101	      debugLogger.error(getErrorMessage(error));
102	    }
103	  }
104	  if (args.all) {
105	    try {
106	      const extensionState = new Map();
107	      await checkForAllExtensionUpdates(
108	        extensions,
109	        extensionManager,
110	        (action) => {
111	          if (action.type === 'SET_STATE') {
112	            extensionState.set(action.payload.name, {
113	              status: action.payload.state,
114	            });
115	          }
116	        },
117	      );
118	      let updateInfos = await updateAllUpdatableExtensions(
119	        extensions,
120	        extensionState,
121	        extensionManager,
122	        () => {},
123	      );
124	      updateInfos = updateInfos.filter(
125	        (info) => info.originalVersion !== info.updatedVersion,
126	      );
127	      if (updateInfos.length === 0) {
128	        debugLogger.log('No extensions to update.');
129	        return;
130	      }
131	      debugLogger.log(updateInfos.map((info) => updateOutput(info)).join('\n'));
132	    } catch (error) {
133	      debugLogger.error(getErrorMessage(error));
134	    }
135	  }
136	}
