138	export const updateCommand: CommandModule = {
139	  command: 'update [<name>] [--all]',
140	  describe:
141	    'Updates all extensions or a named extension to the latest version.',
142	  builder: (yargs) =>
143	    yargs
144	      .positional('name', {
145	        describe: 'The name of the extension to update.',
146	        type: 'string',
147	      })
148	      .option('all', {
149	        describe: 'Update all extensions.',
150	        type: 'boolean',
151	      })
152	      .conflicts('name', 'all')
153	      .check((argv) => {
154	        if (!argv.all && !argv.name) {
155	          throw new Error('Either an extension name or --all must be provided');
156	        }
157	        return true;
158	      }),
159	  handler: async (argv) => {
160	    await handleUpdate({
161	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
162	      name: argv['name'] as string | undefined,
163	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
164	      all: argv['all'] as boolean | undefined,
165	    });
166	    await exitCli();
167	  },
168	};
