const INTEGRITY_KEYCHAIN_SERVICE = 'gemini-cli-extension-integrity';

/**
 * Account name under which the integrity secret key is stored.
 */
const INTEGRITY_KEY_ACCOUNT = 'integrity-secret-key';

/**
 * Length of the hex-encoded secret key (32 random bytes -> 64 hex chars).
 */
const SECRET_KEY_LENGTH = 64;

/**
 * Result of verifying the integrity of an extension's metadata.
 */
export enum IntegrityDataStatus {
  /** The stored signature matches the provided metadata. */
  VERIFIED = 'VERIFIED',
  /** No signature has been stored for this extension yet. */
  MISSING = 'MISSING',
  /** A signature exists but does not match the provided metadata. */
  INVALID = 'INVALID',
}

/**
