 */
interface StoredIntegrityData {
  [extensionName: string]: string;
}

/**
 * Manages cryptographic integrity signatures for extension metadata.
 *
 * A single secret key (stored securely in the OS keychain, or an encrypted
 * file fallback) is used to compute HMAC-SHA256 signatures over the serialized
 * metadata of each extension. Signatures are persisted in a JSON file so that
 * unauthorized modifications to extension metadata can be detected later.
 */
export class ExtensionIntegrityManager {
  private readonly keychainService: KeychainService;
  private secretKeyPromise?: Promise<string>;

  constructor() {
    this.keychainService = new KeychainService(INTEGRITY_KEYCHAIN_SERVICE);
  }

  /**
