   * encrypted file storage otherwise.
   */
  getSecretKey(): Promise<string> {
    return (this.secretKeyPromise ??= this.resolveSecretKey());
  }

  private async resolveSecretKey(): Promise<string> {
    try {
      const existing = await this.keychainService.getPassword(
        INTEGRITY_KEY_ACCOUNT,
      );
      if (existing && existing.length === SECRET_KEY_LENGTH) {
        return existing;
      }
    } catch (error) {
