        'Failed to read extension integrity key from secure storage:',
        error instanceof Error ? error.message : String(error),
      );
    }

    const key = crypto.randomBytes(SECRET_KEY_LENGTH / 2).toString('hex');
    try {
      await this.keychainService.setPassword(INTEGRITY_KEY_ACCOUNT, key);
    } catch (error) {
      debugLogger.warn(
        'Failed to persist extension integrity key to secure storage:',
        error instanceof Error ? error.message : String(error),
      );
    }
    return key;
  }

  /**
   * Computes and stores a cryptographic signature of the given metadata for
   * the named extension.
